const enfermedadData=[{"disease":"Se borró la clave del archivo y aun así alguien la usó una semana después","characteristic":"Seguía en el historial del repositorio y nunca se rotó","opts":["Seguía en el historial del repositorio y nunca se rotó","Alguien la adivinó","El servicio la volvió a activar","Se filtró por el navegador"]},{"disease":"Un token publicó en las redes del proyecto algo que nadie escribió","characteristic":"El token de la red se filtró y no se revocó a tiempo","opts":["El token de la red se filtró y no se revocó a tiempo","La red social falló","Alguien entró a la aplicación","Se perdió la clave anónima"]},{"disease":"Alguien pudo leer los datos de otra familia entera","characteristic":"Se usó la clave de servicio donde tocaba la anónima","opts":["Se usó la clave de servicio donde tocaba la anónima","Las tablas estaban mal hechas","El navegador guardó los datos","Se compartió una contraseña"]},{"disease":"La clave apareció en una conversación del grupo familiar","characteristic":"Se mandó una captura de pantalla sin mirarla antes","opts":["Se mandó una captura de pantalla sin mirarla antes","El chat se hackeó","Alguien la escribió a mano","Se subió al repositorio"]},{"disease":"No se pudo publicar la actualización de la aplicación en los teléfonos","characteristic":"Se perdió la firma del APK, que no se puede rotar","opts":["Se perdió la firma del APK, que no se puede rotar","Caducó la clave de servicio","El repositorio se volvió público","Se acabó el espacio del servicio"]},{"disease":"Venció el dominio y el sitio se apagó sin que nadie pudiera evitarlo","characteristic":"La cuenta tenía un solo custodio y ningún suplente","opts":["La cuenta tenía un solo custodio y ningún suplente","El proveedor cerró","Se filtró la contraseña","Nadie pagó a tiempo por descuido"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Lo que da un poder que no corresponde a quien lo encuentre.","type":"Secreto"},{"s":"La clave que viaja con la aplicación y está diseñada para verse.","type":"Clave anónima"},{"s":"La clave que salta todas las políticas de seguridad por fila.","type":"Clave de servicio"},{"s":"Qué puede hacer quien tenga la llave, en la peor lectura.","type":"El alcance"},{"s":"Las variables del servicio, donde vive sin pasar por el repositorio.","type":"El entorno"},{"s":"Guarda para siempre lo que se subió una sola vez.","type":"El historial"},{"s":"Cambiar la clave para que la vieja deje de abrir.","type":"Rotar"},{"s":"Quién tiene la llave y quién más puede llegar a ella.","type":"Custodio y suplente"},{"s":"La llave que abre voz en vez de datos.","type":"Token de red social"},{"s":"La llave que si se pierde no tiene segunda oportunidad.","type":"Firma del APK"}];
const classifyTaskDB=[{"w":"La clave de servicio","gen":"Naturaleza","n":"Da poder total","g":"Secreto","t":"No sale del entorno"},{"w":"La clave anónima","gen":"Naturaleza","n":"Sola no abre nada","g":"Se puede ver","t":"La protegen las políticas"},{"w":"Un token de red social","gen":"Naturaleza","n":"Publica en tu nombre","g":"Secreto","t":"Abre voz, no datos"},{"w":"El nombre de una tabla","gen":"Naturaleza","n":"No abre nada","g":"Se puede ver","t":"Es estructura, no llave"},{"w":"Rotar la clave en el servicio","gen":"Reacción","n":"La vieja deja de servir","g":"Cierra","t":"Funciona aunque haya copias"},{"w":"Borrar la línea del archivo","gen":"Reacción","n":"Queda en el historial","g":"No cierra","t":"El archivo limpio engaña"},{"w":"La clave de servicio en el repositorio","gen":"Dónde vive","n":"Se sube y se queda","g":"Nunca","t":"Aunque el repositorio sea privado"},{"w":"La clave anónima en el código","gen":"Dónde vive","n":"Tiene que viajar al cliente","g":"Puede ir dentro","t":"Está diseñada para verse"},{"w":"El archivo de firma del APK","gen":"Rotación","n":"Sin segunda oportunidad","g":"No se rota","t":"Se guarda copia aparte"},{"w":"La contraseña de una cuenta","gen":"Rotación","n":"Se cambia y ya","g":"Se rota","t":"El mismo día"}];
const completeTaskDB=[{"s":"Una llave se juzga por lo que puede ___.","opts":["abrir","pesar","durar"],"ans":"abrir"},{"s":"La clave de servicio salta todas las ___.","opts":["politicas","tablas","funciones"],"ans":"politicas"},{"s":"Un secreto vive en las variables del ___.","opts":["servicio","navegador","repositorio"],"ans":"servicio"},{"s":"Lo que se subió una vez se ___, no se borra.","opts":["rota","oculta","comenta"],"ans":"rota"},{"s":"Cada llave necesita custodio y ___.","opts":["suplente","copia","nombre"],"ans":"suplente"},{"s":"Un repositorio privado no está ___.","opts":["cifrado","guardado","publicado"],"ans":"cifrado"},{"s":"La ___ del APK no se puede rotar.","opts":["firma","version","licencia"],"ans":"firma"},{"s":"El ___ se escribe antes del primer archivo de claves.","opts":["gitignore","inventario","respaldo"],"ans":"gitignore"}];
const explainQuestions=[{"q":"Explica por qué la clave anónima puede estar a la vista en el código y la de servicio no.","ans":"Porque tienen alcances opuestos aunque abran el mismo servicio. La clave anónima tiene que viajar con la aplicación para que el navegador pueda hablar con la nube, así que se descarga y se puede leer desde cualquier teléfono; está diseñada para eso. Sola no abre nada, porque quien decide qué ve cada quien son las políticas de seguridad por fila que se estudiaron en la etapa 1. La clave de servicio, en cambio, salta todas esas políticas: con ella se lee y se escribe cualquier fila de cualquier familia sin permiso de nadie. Por eso vive solo en las variables del servicio, la usan las funciones de borde del proyecto, y el propio código lo deja escrito en el aviso de send-chat-push: esa clave no se pone jamás en el cliente. La lección general es que «hay una clave en el código» no es un diagnóstico: la pregunta es qué puede hacer esa clave concreta."},{"q":"Se subió una clave al repositorio y se borró en el commit siguiente. ¿Está resuelto? Explica.","ans":"No. Borrarla deja el archivo limpio y el historial intacto: cualquiera con una copia del repositorio puede ver la versión anterior, y hay copias en cada aparato donde se clonó y en cada respaldo. La clave está quemada aunque el archivo se vea bien. Lo único que cierra la puerta de verdad es rotar, es decir cambiar la clave en el servicio para que la vieja deje de servir; eso funciona aunque la clave ya esté copiada en cien sitios, porque deja de abrir. Se rota el mismo día, antes de investigar si alguien la usó, y después se mira en los registros. Reescribir el historial ayuda para el futuro, pero no alcanza a las copias que ya salieron, así que nunca sustituye a la rotación."},{"q":"¿Por qué un repositorio privado no es un sitio seguro para guardar secretos?","ans":"Porque privado significa «no lo ve cualquiera», no significa cifrado. Lo ve todo el que tenga acceso, lo ve quien tenga un token robado de alguna de esas cuentas, y lo ve el mundo entero el día que alguien cambie la visibilidad por error, que son dos clics. Además el contenido queda en el historial, en los clones y en los respaldos, así que un cambio de visibilidad expone también el pasado y no solo el estado actual. La regla se sostiene igual de estricta: dentro de un repositorio, aunque sea privado, no van secretos. Lo privado sirve para proteger el contenido de la casa, que es el motivo por el que F.A.R.O lo es, pero no para proteger las llaves de la casa."},{"q":"Explica qué es el alcance de una llave y por qué se mide en la peor lectura posible.","ans":"El alcance es qué puede hacer quien tenga la llave, y es lo que decide si algo es un secreto o no, mucho más que dónde esté guardado. Se mide en la peor lectura posible y no en la que uno tenía en mente porque quien la encuentre no va a usarla como estaba previsto: va a usarla para todo lo que permita. Un token que se pidió para publicar una foto puede servir también para borrar publicaciones o leer mensajes, según lo que se le concedió al pedirlo. De ahí sale la regla del alcance mínimo: cada llave debe dar el poder justo para su trabajo, porque una llave que sirve para todo es una llave que, perdida, lo pierde todo. Y de ahí sale también la clasificación de esta etapa: hay llaves que abren datos y hay llaves que abren voz, y las segundas hacen un daño que no se mide en información sino en confianza."},{"q":"¿Qué es un custodio, por qué siempre lleva suplente, y qué llave del proyecto lo enseña?","ans":"El custodio es quien tiene la llave; el suplente es quien más puede llegar a ella si el custodio falta. No es lo mismo compartir la clave que compartir cómo se recupera: basta con que el suplente sepa dónde está guardada y pueda alcanzarla. Se hace así porque una llave con un solo custodio se siente segura, ya que nadie más puede filtrarla, y en realidad es un punto único de fallo con otro nombre: si esa persona falta, el proyecto no puede seguir. La llave que lo enseña en esta casa es la de la cuenta del dominio: si solo una persona sabe dónde está, el día que falte no se renueva y el sitio se apaga solo, sin que nadie pueda evitarlo. Por eso el inventario de llaves lleva las dos columnas y por eso el testamento técnico de la Ruta de la Ingeniería pide exactamente lo mismo."},{"q":"Cuenta cómo se filtran de verdad los secretos y qué costumbre lo evita.","ans":"Casi nunca por un ataque. Se filtran por una captura de pantalla mandada por chat para pedir ayuda, con un token visible en una esquina que nadie miró; por un archivo de prueba en el que se puso la clave «un momento» y acabó subido; por un correo reenviado con la conversación entera debajo; y por la prisa de un martes. En todos esos casos no hay fallo de programación: hay una persona que no sabía que estaba mandando una llave. Las costumbres que lo evitan son cortas y no son técnicas: antes de mandar una captura, mirar la captura y recortar si hay duda; no escribir nunca una clave en un archivo del proyecto, ni siquiera temporalmente, porque ese temporalmente es el momento exacto en que se filtra; y si algo ya salió, rotar sin discutir si alguien lo vio. Ante la duda se rota, porque rotar cuesta cinco minutos y no rotar cuesta el proyecto."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

