function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"En js/auth.js y js/chat.js hay una clave de Supabase escrita en el código, que se descarga con la aplicación y cualquiera puede leer desde su teléfono."},{"txt":"Las seis funciones de borde del proyecto corren con la clave de servicio, que salta todas las políticas de seguridad por fila. Una de ellas necesita esa clave para poder ver las suscripciones de aviso."},{"txt":"La Antena publica en redes sociales, así que hay funciones de autorización y un token guardado por cada red conectada al proyecto."},{"txt":"F.A.R.O vive en un repositorio privado y ahí está el material de la casa. Alguien propone guardar también ahí un archivo con las claves, total, nadie más lo ve."},{"txt":"El .gitignore del proyecto tiene una sola línea. Hoy no hay archivos de claves, pero mañana hay que crear el primero para probar una función nueva."},{"txt":"La aplicación se entrega como APK a los cuatro teléfonos de la familia, y ese APK va firmado con una llave que se generó una vez."},{"txt":"Algo no funciona, se abre el panel del servicio y se manda una captura por el grupo de la familia para pedir ayuda. En una esquina de la imagen se ve un token entero."},{"txt":"La cuenta del dominio, la del servicio y la de la tienda están a nombre de una sola persona, y solo esa persona sabe dónde están las claves."}];
const critCaseQuestions=["1. ¿Qué puede hacer quien tenga esa llave, en la peor lectura?","2. ¿Dónde debería vivir, y por qué ahí y no en otro sitio?","3. ¿Hay que rotar? Si no se puede rotar, ¿qué se hace en su lugar?","4. Escribe en 3-4 frases quién la custodia, quién es el suplente y qué queda anotado."];
const critCaseGuides=["El alcance se mide en la peor lectura, no en la prevista: quien la encuentre la va a usar para todo lo que permita. Hay llaves que abren datos y llaves que abren voz, y esas segundas hacen daño en confianza y no en información.","La clave anónima va en el código porque tiene que viajar al navegador; la de servicio va en las variables del servicio y nunca en el repositorio, aunque sea privado; la firma del APK vive fuera y con copia en otro sitio físico.","Casi todo se rota, y se rota el mismo día, antes de investigar. Lo que no se puede rotar (la firma del APK) cambia de categoría entera: copia aparte, anotada en el testamento técnico y probada una vez al año.","Cada fila del inventario lleva custodio y suplente con nombre, y ninguna columna es la clave. Lo que se anota es dónde está y cómo se recupera, no el secreto."];

const critErrorBank=[{"txt":"\"Hay una clave escrita en el código de la aplicación, hay que sacarla de ahí ya\".","g1":"Depende de cuál. La clave anónima tiene que estar ahí para que el navegador pueda hablar con la nube, y está diseñada para verse: sola no abre nada.","g2":"Lo que la protege son las políticas de seguridad por fila. Si esas estuvieran mal escritas, esta misma clave abriría la casa entera: es pública porque las políticas están puestas."},{"txt":"\"Ya borré la clave del archivo y volví a subir, quedó resuelto\".","g1":"El archivo quedó limpio y el historial no: cualquiera con una copia del repositorio ve la versión anterior, y hay copias en cada clon y en cada respaldo.","g2":"Lo único que cierra es rotar la clave en el servicio, hoy mismo y antes de investigar nada. Reescribir el historial ayuda para el futuro pero no alcanza a las copias que ya salieron."},{"txt":"\"El repositorio es privado, ahí podemos guardar el archivo de claves\".","g1":"Privado significa que no lo ve cualquiera, no que esté cifrado. Lo ve quien tenga acceso, quien tenga un token robado, y todo el mundo el día que alguien cambie la visibilidad con dos clics.","g2":"Dentro de un repositorio no van secretos, aunque sea privado. Lo privado sirve para el contenido de la casa, no para las llaves de la casa."},{"txt":"\"El token de la red social no importa tanto, total no tiene datos de nadie\".","g1":"No abre datos: abre voz. Quien lo tenga publica en nombre del proyecto, y eso se descubre cuando ya lo vio todo el mundo.","g2":"El daño no se mide en información perdida sino en confianza, que es más lenta de reconstruir. Se revisan cada cierto tiempo y se revocan los de redes que ya no se usan."},{"txt":"\"La firma del APK la tengo yo en la computadora, no hace falta más\".","g1":"Esa es la única llave del proyecto que no se puede rotar: si se pierde, no hay forma de publicar una actualización de esa misma aplicación y hay que reinstalar en todos los aparatos.","g2":"Cambia de categoría: copia en otro sitio físico, anotada en el testamento técnico, y una prueba al año de que la copia sirve de verdad."},{"txt":"\"Solo yo sé dónde están las claves, así están más seguras\".","g1":"Se siente seguro porque nadie más puede filtrarlas, y lo que significa de verdad es que el proyecto entero cabe en una cabeza.","g2":"Cada llave necesita custodio y suplente. No hay que compartir la clave: basta con que el suplente sepa dónde está guardada y pueda llegar a ella el día que haga falta."}];

const critDecisionBank=["Una clave a la vista en el código del cliente: ¿se saca, se deja o depende? ¿De qué depende?","Una función necesita ver filas de todas las familias: ¿qué llave se le da y dónde vive?","Los tokens de las redes conectadas a la Antena: ¿cada cuánto se revisan y qué se hace con los que ya no se usan?","Alguien propone guardar el archivo de claves en el repositorio privado: ¿qué respondes y con qué argumento?","Hay que crear el primer archivo con una clave para probar: ¿qué se hace antes de escribir la primera letra?","La firma del APK: ¿dónde vive, quién la custodia y qué se prueba una vez al año?","Una captura con un token salió por el grupo de la familia: ¿qué se hace primero y qué se hace después?","Todas las cuentas están a nombre de una sola persona: ¿qué se cambia y qué queda escrito?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Rotar la clave el mismo día que aparece en el repositorio.","b":"Borrar la línea y revisar después si alguien la usó.","ga":"Caso A: la llave vieja deja de abrir aunque esté copiada en cien sitios. Cuesta cinco minutos y cierra de verdad.","gb":"Caso B: el archivo se ve limpio y la llave sigue sirviendo. Se investiga con la puerta abierta, que es el peor momento para investigar."},{"a":"Guardar la clave de servicio en las variables del servicio.","b":"Guardarla en un archivo del repositorio privado.","ga":"Caso A: no pasa por el repositorio ni por el navegador, así que no hay historial, ni clones, ni respaldos con la llave dentro.","gb":"Caso B: queda en el historial para siempre y depende de que nadie cambie la visibilidad ni pierda un token de acceso."},{"a":"Una llave con custodio y suplente.","b":"Una llave que solo conoce una persona.","ga":"Caso A: si falta el custodio, el suplente sabe dónde está y cómo llegar a ella. El proyecto sigue.","gb":"Caso B: se siente más seguro y en realidad es un punto único de fallo: el día que falte esa persona, el dominio no se renueva y el sitio se apaga solo."},{"a":"Escribir el .gitignore antes de crear el archivo de claves.","b":"Añadirlo al .gitignore en cuanto se note el problema.","ga":"Caso A: el archivo nunca entra al historial, así que no hay nada que rotar ni que reescribir.","gb":"Caso B: llega tarde por definición. El archivo ya se subió al menos una vez y la clave ya está quemada."}];

const critCauseBank=[{"cause":"Se juzga una llave por si está a la vista y no por lo que abre.","guide":"Se saca del código la clave anónima, que tiene que estar ahí, y se deja tranquila la de servicio si nadie preguntó qué hace. Se arregla lo que no estaba roto y se deja lo que sí."},{"cause":"Se escribe una clave en un archivo «un momento, para probar».","guide":"Ese momento es cuando se filtran casi todas: el archivo se guarda, se sube con el resto y nadie vuelve a mirarlo. No hay ataque, hay prisa."},{"cause":"Se borra la clave del archivo y no se rota.","guide":"El historial la conserva, y también los clones y los respaldos. La llave sigue abriendo y el archivo limpio da una sensación de resuelto que es lo más peligroso."},{"cause":"Se confía en que el repositorio es privado.","guide":"Privado no es cifrado: lo ve quien tenga acceso o un token robado, y lo ve todo el mundo el día que alguien cambie la visibilidad sin querer."},{"cause":"Se manda una captura de pantalla sin mirarla.","guide":"Es la vía de filtración más común y la menos vigilada. La imagen se reenvía, se respalda en la nube del teléfono y se queda ahí para siempre."},{"cause":"Se guarda una llave con un solo custodio.","guide":"El proyecto entero pasa a depender de una persona. No es seguridad: es un punto único de fallo con nombre de precaución."}];
const critEffectBank=[{"effect":"Una clave apareció en el repositorio y no pasó nada.","guide":"Se rotó el mismo día, antes de investigar. La que estaba subida dejó de abrir, así que las copias que hubiera quedaron sin valor."},{"effect":"Nadie tuvo que discutir si la clave del código era un problema.","guide":"Estaba en el inventario con su alcance escrito: clave anónima, protegida por las políticas por fila. La pregunta ya tenía respuesta antes de hacerse."},{"effect":"El dominio se renovó a tiempo estando el custodio de viaje.","guide":"Había suplente, y el suplente sabía dónde estaba guardada la clave y cómo llegar a ella. No hizo falta compartir el secreto, solo el camino."},{"effect":"Se pudo publicar una actualización del APK dos años después.","guide":"La firma estaba guardada fuera del repositorio, con copia en otro sitio, y una vez al año alguien comprobaba que la copia servía."},{"effect":"Un token de red social dejó de existir antes de hacer daño.","guide":"Se revisaban cada cierto tiempo y se revocaban los de redes que ya no se usaban, así que el que se filtró llevaba meses sin servir."},{"effect":"Una captura con un token no acabó en filtración.","guide":"Se miró la imagen antes de mandarla y se recortó la esquina. Y como quedó la duda, se rotó igual: cuesta cinco minutos."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El llavero sobre la mesa · Forma ${cf} · Llaves y secretos · Ruta de la Casa Cerrada`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La llave sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué puede abrir esa llave, dónde debería vivir y hay que rotarla? Explica por qué tu respuesta cierra la puerta de verdad, en vez de dejar el archivo limpio y la llave abriendo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos deja la puerta cerrada de verdad, y por qué? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El llavero sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La llave sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué puede abrir esa llave, dónde debería vivir y hay que rotarla? Explica por qué tu respuesta cierra la puerta de verdad, en vez de dejar el archivo limpio y la llave abriendo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos deja la puerta cerrada de verdad, y por qué? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El llavero sobre la mesa Llaves y secretos · Ruta de la Casa Cerrada · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El llavero sobre la mesa · Llaves y secretos · Ruta de la Casa Cerrada · Etapa 4 · Ciberseguridad</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El llavero sobre la mesa · Llaves y secretos · Ruta de la Casa Cerrada · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🤫","label":"El secreto","text":"Lo que da <strong>un poder que no corresponde</strong> a quien lo encuentre. <strong>Se reconoce:</strong> preguntando qué haría alguien con esto. <strong>Se pierde:</strong> creyendo que secreto es lo que está escondido. <strong>Aquí:</strong> la clave anónima está a la vista y no lo es."},{"y":"2","icon":"👑","label":"El alcance","text":"Qué puede hacer quien la tenga, <strong>en la peor lectura</strong>. <strong>Se mide:</strong> por lo que permite, no por lo previsto. <strong>Se pierde:</strong> pidiendo más permisos de los necesarios. <strong>Aquí:</strong> la clave de servicio salta todas las políticas."},{"y":"3","icon":"🏠","label":"El entorno","text":"Dónde vive: <strong>las variables del servicio</strong>. <strong>Sirve para:</strong> que no pase por el repositorio ni por el navegador. <strong>Se pierde:</strong> en el archivo de prueba de un martes. <strong>Aquí:</strong> ahí viven las llaves de las seis funciones de borde."},{"y":"4","icon":"📜","label":"El historial","text":"La memoria del repositorio, que <strong>no olvida nunca</strong>. <strong>Guarda:</strong> cada versión de cada archivo. <strong>Se pierde:</strong> creyendo que borrar una línea borra el pasado. <strong>Aquí:</strong> el .gitignore tiene una sola línea, y hay que revisarlo antes del primer archivo de claves."},{"y":"5","icon":"🔄","label":"La rotación","text":"Cambiar la clave para que <strong>la vieja deje de abrir</strong>. <strong>Sirve para:</strong> cerrar de verdad, aunque haya copias. <strong>Se pierde:</strong> dejándolo para el fin de semana. <strong>Aquí:</strong> se rota el mismo día, antes de investigar."},{"y":"6","icon":"👤","label":"El custodio","text":"Quién la tiene, y <strong>quién más puede llegar a ella</strong>. <strong>Sirve para:</strong> que el proyecto no quepa en una cabeza. <strong>Se pierde:</strong> guardando la llave «por seguridad» sin decírselo a nadie. <strong>Aquí:</strong> el dominio, el servicio y la tienda."},{"y":"7","icon":"🚪","label":"La salida","text":"Qué se hace <strong>el día que un secreto se escapa</strong>. <strong>Orden:</strong> rotar, comprobar, mirar registros, anotar y contarlo. <strong>Se pierde:</strong> callándolo por vergüenza. <strong>Aquí:</strong> una filtración callada se repite."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(rotaLaClave){sfx(rotaLaClave?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(rotaLaClave){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔄</span><span class="ms-text"><strong>Rotaste la clave el mismo día:</strong> la que estaba subida dejó de abrir, así que las copias que hubiera quedaron sin valor.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📋</span><span class="ms-text"><strong>Y después lo demás:</strong> comprobar que la aplicación sigue viva, mirar los registros, anotarlo en el inventario y contarlo en casa. Cinco minutos.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🧽</span><span class="ms-text"><strong>Borraste la línea:</strong> el archivo quedó limpio y la sensación fue de problema resuelto.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📜</span><span class="ms-text"><strong>Y la llave sigue abriendo:</strong> está en el historial, en cada clon y en cada respaldo. Lo único que cambió es que ahora nadie la está mirando.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"secreto":{"nombre":"Qué es un secreto","icon":"🤫","estructura":{"title":"Qué es","info":"• Lo que da <strong>un poder que no corresponde</strong> a quien lo encuentre<br>• No es lo que está escondido: hay claves a la vista que no son secretas<br>• Y archivos privados que sí lo son"},"funcion":{"title":"Cómo se hace","info":"• Se pregunta: <strong>¿qué haría alguien si encuentra esto?</strong><br>• Si la respuesta incomoda, es un secreto<br>• Y entonces vale la segunda pregunta: ¿este sitio se sube?"},"enfermedades":{"title":"Dónde se pierde","info":"• Cuando se confunde secreto con escondido<br>• Cuando se protege lo que se ve y se olvida lo que no<br>• Cuando nadie ha hecho nunca la lista de las llaves que existen"},"cuidados":{"title":"En este proyecto","info":"• La <strong>clave anónima</strong> está en js/auth.js y no es un secreto<br>• La <strong>clave de servicio</strong> sí lo es, y no aparece en ningún archivo<br>• Los <strong>tokens de la Antena</strong> también, y abren voz en vez de datos"}},"alcance":{"nombre":"El alcance","icon":"👑","estructura":{"title":"Qué es","info":"• Qué puede hacer quien tenga la llave<br>• Se mide <strong>en la peor lectura</strong>, no en la prevista<br>• Es lo que decide si algo es secreto, más que dónde esté"},"funcion":{"title":"Cómo se hace","info":"• Se escribe al lado de cada llave, en una frase<br>• Regla del <strong>alcance mínimo</strong>: el poder justo para su trabajo<br>• Una llave que sirve para todo, perdida, lo pierde todo"},"enfermedades":{"title":"Dónde se pierde","info":"• Al pedir permisos de más «por si acaso» al conectar un servicio<br>• Al usar la llave de servicio donde bastaba la del visitante<br>• Al suponer que un token solo hace aquello para lo que se pidió"},"cuidados":{"title":"En este proyecto","info":"• Anónima: <strong>no abre nada sola</strong>, la frenan las políticas por fila<br>• De servicio: <strong>todas las filas de todas las familias</strong><br>• Token de red: <strong>publica en nombre del proyecto</strong>"}},"entorno":{"nombre":"El entorno","icon":"🏠","estructura":{"title":"Qué es","info":"• Las <strong>variables del servicio</strong>: el sitio donde vive un secreto<br>• No pasa por el repositorio ni llega al navegador<br>• Si una clave no puede vivir ahí, hay que preguntarse por qué"},"funcion":{"title":"Cómo se hace","info":"• Se carga una vez en el panel del servicio y no se copia a ningún lado<br>• El código la pide por su nombre, nunca la escribe<br>• Lo que sí se escribe es <strong>el nombre de la variable</strong>"},"enfermedades":{"title":"Dónde se pierde","info":"• En el archivo de prueba de «lo pongo aquí un momento»<br>• En el <code>.gitignore</code> que se escribió tarde<br>• En una captura de pantalla del panel, mandada por chat"},"cuidados":{"title":"En este proyecto","info":"• Ahí viven las llaves de las <strong>seis funciones de borde</strong><br>• El <code>.gitignore</code> tiene <strong>una sola línea</strong>: se revisa antes del primer archivo de claves<br>• El repositorio es privado, y aun así no lleva secretos"}},"rotacion":{"nombre":"La rotación","icon":"🔄","estructura":{"title":"Qué es","info":"• Cambiar la clave para que <strong>la vieja deje de abrir</strong><br>• Es lo único que cierra la puerta de verdad<br>• Funciona aunque la clave ya esté copiada en cien sitios"},"funcion":{"title":"Cómo se hace","info":"• <strong>Primero se rota</strong>, el mismo día, antes de investigar<br>• Luego se comprueba que la aplicación sigue funcionando<br>• Después se miran los registros, se anota y <strong>se cuenta en casa</strong>"},"enfermedades":{"title":"Dónde se pierde","info":"• Al dejarlo para el fin de semana «porque seguro nadie la vio»<br>• Al creer que borrar el archivo sustituye a rotar<br>• Al callarlo por vergüenza: una filtración callada se repite"},"cuidados":{"title":"En este proyecto","info":"• Se rota: la de servicio, los tokens y las contraseñas<br>• <strong>No se rota: la firma del APK</strong>, así que lleva copia aparte<br>• Ante la duda de si alguien la vio, <strong>se rota igual</strong>"}}};
let labParte='secreto',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🗝️ ¡'+name+' completó la Etapa 4 de la Ruta de la Casa Cerrada (Llaves y secretos)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

